import main
assert main.transition_offer('NONE','offer_sent')=='OFFERED'
assert main.transition_offer('OFFERED','offer_accepted')=='ACCEPTED'
assert main.transition_offer('OFFERED','offer_declined')=='DECLINED'
assert main.transition_offer('OFFERED','offer_withdrawn')=='WITHDRAWN'
for s,e in [('ACCEPTED','offer_withdrawn'),('WITHDRAWN','offer_accepted'),('NONE','offer_accepted'),('ACCEPTED','offer_accepted')]:
    try: main.transition_offer(s,e)
    except ValueError: pass
    else: raise AssertionError(f'Illegal offer transition: {s}/{e}')

